class Solution {
  public String validIPAddress(String queryIP) {
    if (queryIP.chars().filter(c -> c == '.').count() == 3 && isV4(queryIP)) return "IPv4";
    if (queryIP.chars().filter(c -> c == ':').count() == 7 && isV6(queryIP)) return "IPv6";
    return "Neither";
  }

  private boolean isV4(String ip) {
    for (String part : ip.split("\\.", -1)) {
      if (part.isEmpty() || part.length() > 3 || (part.length() > 1 && part.charAt(0) == '0')) return false;
      for (char c : part.toCharArray()) if (!Character.isDigit(c)) return false;
      if (Integer.parseInt(part) > 255) return false;
    }
    return true;
  }

  private boolean isV6(String ip) {
    for (String part : ip.split(":", -1)) {
      if (part.isEmpty() || part.length() > 4) return false;
      for (char c : part.toCharArray()) if (Character.digit(c, 16) < 0) return false;
    }
    return true;
  }
}
